def transform(grid: np.ndarray) -> np.ndarray:
    h, w = grid.shape
    period = h
    for p in range(1, h):
        if np.array_equal(grid[:-p], grid[p:]):
            period = p
            break
    ext = np.array([grid[r % period] for r in range(9)])
    return F3Primitives.replace_color(ext, 1, 2)

def transform(grid: np.ndarray) -> np.ndarray:
    res = np.zeros_like(grid)
    for col in np.unique(grid):
        if col == 0:
            continue
        mask = (grid == col)
        rows = np.unique(np.where(mask)[0])
        rmax = rows.max()
        cmax = np.where(mask)[1].max()
        for r in rows:
            cols = np.where(mask[r])[0]
            if r < rmax:
                for c in cols:
                    nc = c + 1 if (cols.max() < cmax or c < cmax) else c
                    res[r, nc] = col
            else:
                for c in cols:
                    res[r, c] = col
    return res

def transform(grid: np.ndarray) -> np.ndarray:
    res = grid.copy()
    vals, counts = np.unique(grid[grid != 0], return_counts=True)
    if len(vals) == 0:
        return res
    main_color = int(vals[np.argmax(counts)])
    mr, mc = np.where(grid == main_color)
    mr0, mr1, mc0, mc1 = int(mr.min()), int(mr.max()) + 1, int(mc.min()), int(mc.max()) + 1
    tmpl = (grid[mr0:mr1, mc0:mc1] == main_color).astype(int)
    th, tw = tmpl.shape
    for o in F3Primitives.get_connected_objects(grid):
        if o['color'] == main_color:
            continue
        r0, c0, r1, c1 = o['bbox']
        col = o['color']
        dr = -1 if r1 <= mr0 else (1 if r0 >= mr1 else 0)
        dc = -1 if c1 <= mc0 else (1 if c0 >= mc1 else 0)
        if dr == 0 and dc == 0:
            continue
        for k in range(1, 6):
            sr = mr0 + k * dr * (th + 1)
            sc = mc0 + k * dc * (tw + 1)
            for rr in range(th):
                for cc_i in range(tw):
                    if tmpl[rr, cc_i] and 0 <= sr + rr < res.shape[0] and 0 <= sc + cc_i < res.shape[1]:
                        res[sr + rr, sc + cc_i] = col
    return res

