def transform(grid: np.ndarray) -> np.ndarray:
    h, w = grid.shape
    cmap = {}
    for r in range(h):
        for c in range(w):
            if grid[r, c] != 0:
                cmap[(r + c) % 3] = int(grid[r, c])
    res = np.zeros_like(grid)
    for r in range(h):
        for c in range(w):
            res[r, c] = cmap.get((r + c) % 3, 0)
    return res

def transform(grid: np.ndarray) -> np.ndarray:
    red = (grid == 2)
    cyan = (grid == 8)
    if not np.any(red) or not np.any(cyan):
        return grid.copy()
    rr, rc = np.where(red)
    cr, cc = np.where(cyan)
    dr, dc = 0, 0
    if rr.max() < cr.min():
        dr = int(cr.min() - rr.max() - 1)
    elif rr.min() > cr.max():
        dr = int(cr.max() - rr.min() + 1)
    elif rc.max() < cc.min():
        dc = int(cc.min() - rc.max() - 1)
    elif rc.min() > cc.max():
        dc = int(cc.max() - rc.min() + 1)
    res = np.where(red, 0, grid)
    moved_red = F3Primitives.translate_object(np.where(red, 2, 0), dr, dc, bg_color=0)
    return np.where(moved_red != 0, 2, res)

def transform(grid: np.ndarray) -> np.ndarray:
    res = grid.copy()
    sep_color = int(grid[2, 2])
    cells = grid[0::3, 0::3].copy()
    colors = [int(c) for c in np.unique(cells) if c != 0 and c != sep_color]
    conn = np.zeros_like(cells)
    for col in colors:
        layer = F3Primitives.draw_connecting_lines(np.where(cells == col, col, 0), col, col)
        conn = np.where(layer == col, col, conn)
    for r in range(conn.shape[0]):
        for c in range(conn.shape[1]):
            if conn[r, c] != 0:
                res[3*r:3*r+2, 3*c:3*c+2] = conn[r, c]
    return res

