def transform(grid: np.ndarray) -> np.ndarray:
    res = grid.copy()
    h, w = grid.shape
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            c_center = int(grid[r, c])
            c_petal = int(grid[r - 1, c])
            if c_center != 0 and c_petal != 0 and c_center != c_petal:
                if grid[r+1, c] == c_petal and grid[r, c-1] == c_petal and grid[r, c+1] == c_petal:
                    for d in [-2, -1, 1, 2]:
                        if 0 <= r + d < h:
                            res[r + d, c] = c_petal
                        if 0 <= c + d < w:
                            res[r, c + d] = c_petal
                        if 0 <= r + d < h and 0 <= c + d < w:
                            res[r + d, c + d] = c_center
                        if 0 <= r + d < h and 0 <= c - d < w:
                            res[r + d, c - d] = c_center
    return res

