def transform(grid: np.ndarray) -> np.ndarray:
    res = grid.copy()
    h, w = grid.shape
    best_pr, best_pc = 1, 1
    for pr in range(2, 10):
        ok = True
        for r in range(h - pr):
            m = (grid[r] != 0) & (grid[r + pr] != 0)
            if np.any(grid[r, m] != grid[r + pr, m]):
                ok = False
                break
        if ok:
            best_pr = pr
            break
    for pc in range(2, 10):
        ok = True
        for c in range(w - pc):
            m = (grid[:, c] != 0) & (grid[:, c + pc] != 0)
            if np.any(grid[m, c] != grid[m, c + pc]):
                ok = False
                break
        if ok:
            best_pc = pc
            break
    for r in range(h):
        for c in range(w):
            if res[r, c] == 0:
                vals = grid[r % best_pr::best_pr, c % best_pc::best_pc]
                nz = vals[vals != 0]
                if len(nz) > 0:
                    res[r, c] = nz[0]
    return res

def transform(grid: np.ndarray) -> np.ndarray:
    h, w = grid.shape
    vals, counts = np.unique(grid[grid != 0], return_counts=True)
    if len(vals) == 0:
        return grid.copy()
    body_color = int(vals[np.argmax(counts)])
    vis = np.zeros((h, w), dtype=bool)
    templates = []
    dot_list = []
    for r in range(h):
        for c in range(w):
            if grid[r, c] != 0 and not vis[r, c]:
                q = [(r, c)]
                vis[r, c] = True
                pts = []
                while q:
                    cr, cc = q.pop()
                    pts.append((cr, cc))
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr, nc] != 0 and not vis[nr, nc]:
                                vis[nr, nc] = True
                                q.append((nr, nc))
                if any(grid[pr, pc] == body_color for pr, pc in pts):
                    rs = [p[0] for p in pts]
                    cs = [p[1] for p in pts]
                    r0, r1, c0, c1 = min(rs), max(rs) + 1, min(cs), max(cs) + 1
                    sub = np.zeros((r1 - r0, c1 - c0), dtype=grid.dtype)
                    for pr, pc in pts:
                        sub[pr - r0, pc - c0] = grid[pr, pc]
                    templates.append(sub)
                else:
                    for pr, pc in pts:
                        dot_list.append((pr, pc, int(grid[pr, pc])))
    res = np.zeros_like(grid)
    for tmpl in templates:
        transforms = []
        for k in range(4):
            rot = np.rot90(tmpl, k)
            transforms.append(rot)
            transforms.append(np.fliplr(rot))
        placed = False
        for t in transforms:
            if placed:
                break
            th, tw = t.shape
            anchors = [(r, c, int(t[r, c])) for r in range(th) for c in range(tw) if t[r, c] != 0 and t[r, c] != body_color]
            if not anchors:
                continue
            ar, ac, acol = anchors[0]
            for dr, dc, dcol in dot_list:
                if acol == dcol:
                    sr, sc = dr - ar, dc - ac
                    if all((sr + a2r, sc + a2c, a2col) in dot_list for a2r, a2c, a2col in anchors):
                        for rr in range(th):
                            for cc in range(tw):
                                if t[rr, cc] != 0 and 0 <= sr + rr < res.shape[0] and 0 <= sc + cc < res.shape[1]:
                                    res[sr + rr, sc + cc] = t[rr, cc]
                        placed = True
                        break
    return res

def transform(grid: np.ndarray) -> np.ndarray:
    tiled = F3Primitives.tile_grid(grid, 2, 2)
    res = tiled.copy()
    h, w = tiled.shape
    for r in range(h):
        for c in range(w):
            if tiled[r, c] != 0:
                for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                    if 0 <= r + dr < h and 0 <= c + dc < w and res[r + dr, c + dc] == 0:
                        res[r + dr, c + dc] = 8
    return res

def transform(grid: np.ndarray) -> np.ndarray:
    coords = np.argwhere(grid != 0)
    rmin, cmin = coords.min(axis=0)
    rmax, cmax = coords.max(axis=0)
    res = grid.copy()
    best_cr, best_cc = (rmin + rmax) / 2.0, (cmin + cmax) / 2.0
    best_score = -1
    for cr2 in range(int(2 * rmin), int(2 * rmax) + 1):
        for cc2 in range(int(2 * cmin), int(2 * cmax) + 1):
            cr, cc = cr2 / 2.0, cc2 / 2.0
            ok = True
            cnt = 0
            for r in range(grid.shape[0]):
                for c in range(grid.shape[1]):
                    if grid[r, c] != 0:
                        for nr, nc in [(int(round(2*cr - r)), c), (r, int(round(2*cc - c))), (int(round(cr + (c - cc))), int(round(cc + (r - cr))))]:
                            if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                                if grid[nr, nc] != 0 and grid[nr, nc] != grid[r, c]:
                                    ok = False
                                elif grid[nr, nc] == grid[r, c]:
                                    cnt += 1
                            else:
                                ok = False
            if ok and cnt > best_score:
                best_score = cnt
                best_cr, best_cc = cr, cc
    cr, cc = best_cr, best_cc
    for _ in range(3):
        pts = np.argwhere(res != 0)
        for r, c in pts:
            val = res[r, c]
            for nr, nc in [
                (int(round(2*cr - r)), c),
                (r, int(round(2*cc - c))),
                (int(round(2*cr - r)), int(round(2*cc - c))),
                (int(round(cr + (c - cc))), int(round(cc + (r - cr)))),
                (int(round(cr - (c - cc))), int(round(cc - (r - cr))))
            ]:
                if 0 <= nr < grid.shape[0] and 0 <= nc < res.shape[1] and res[nr, nc] == 0:
                    res[nr, nc] = val
    return res
